                              </>
                            )
                          ) : (
                            narrative.xai_narrative
                          )}
                        </>
                      )
                    ) : (
                      <span className="text-gray-500 italic">No narrative available</span>
                    )}
                  </div>
                </div>
              );})}
            </div>
          )}
        </div>
      </div>

      {/* Audit Highlights */}
      <div className="card">
