            className="underline font-semibold hover:opacity-80"
          >
            View Incident
          </a>
        </div>
      )}
    </>
  );

  // ── Raw Payload Tab ──────────────────────────────────────────────────

  const renderRawPayloadTab = () => (
    <div>
      <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
